from pathlib import Path
import json,statistics,collections,gzip,csv,io
root=Path.cwd()
regions=['Floresta','Caverna','Ruinas','Pantano','Vulcao','Abismo','Fortaleza','Necropole','Citadela','Panteao','Cataclismo','Paradoxo']
names={'paladino':'Paladino','berserker':'Berserker','samurai':'Samurai','ninja':'Ninja','sniper':'Sniper','atirador_arcano':'Atirador Arcano','espreitador':'Espreitador','guarda_florestal':'Guarda Florestal','mago_incendiario':'Incendiário','mago_frigido':'Frígido','arquimago':'Arquimago','corrompido':'Corrompido','druida_sombrio':'Druida Sombrio','avatar_da_natureza':'Avatar da Natureza','fada_monarca':'Fada Monarca','protetor_da_floresta':'Protetor da Floresta'}
lines=['# Reavaliação da progressão — 06/11/2026','','192 campanhas: 16 especializações × três sementes (101, 202, 303) × antes/depois × dois cenários de equipamento. Antes usa os quatro arquivos de mecânica do commit 601d32f; depois usa as habilidades, IA, equipamentos e crítico universais atuais. A régua continua sendo o alcance da maioria, não a obrigação de concluir o jogo.','', '## Método e limites','','Motor real do jogo, atributos equilibrados, política heurística de habilidades compartilhada entre versões. A política foi corrigida para incluir os 5% da vida máxima por turno de Golpes Velozes ao avaliar a ação, tanto antes quanto depois. Isso impede atribuir a melhora de uma rotação corrigida apenas aos novos coeficientes. A IA inimiga e os conjuntos da rodada anterior estão presentes em ambos os lados. Sem poções, torre, dungeon ou arena. Recuperação completa entre lutas. Cada derrota/fuga oferece um nível até 100; falhas repetidas melhoram uma peça. A campanha termina ao vencer o último chefe ou acumular 11 mortes já no nível 100 com seis lendários. Não mede tempo de farm nem custo real da preparação. Três sementes são uma amostra pequena, e mudanças nos críticos alteram a sequência de RNG: diferenças descritivas, sem isolamento causal de cada ajuste.','','Referência: conserva o equipamento inicial Floresta/Caverna ao melhorar, com acessório da Floresta. Conjuntos por rota: nas preparações, troca gratuitamente as peças já existentes pelo conjunto preferido liberado, preservando raridade e acessório; não cria espaços antes vazios. Essa concessão existe igualmente antes/depois e serve para comparar sinergias, não para simular economia. A escolha é pré-definida, não uma busca pelo melhor conjunto ou rotação. Ganhar poder não garante uma trajetória de RNG mais favorável.','']
summary=[]
for label,folder in [('Referência','progression-w14-2026-11-06'),('Conjuntos por rota','progression-w14-sets-2026-11-06')]:
 d=root/'docs/qa'/folder
 files=sorted(d.glob('*.json'));runs=[dict(json.loads(f.read_text(encoding='utf-8')),version=f.name.split('-')[0]) for f in files] if files else json.loads(gzip.decompress((d/'results.json.gz').read_bytes()))['runs']
 assert len(runs)==96,(folder,len(runs))
 lines += ['## '+label,'']
 for version in ['before','after']:
  a=[r for r in runs if r['version']==version];indices=[regions.index(r['region'])+1 for r in a]
  lines += [f"{'Antes' if version=='before' else 'Depois'}: {sum(r['fights'] for r in a)} lutas; {sum(r['deaths'] for r in a)} mortes; {sum(r['reason']=='Paradoxo derrotado' for r in a)}/48 conclusões; {sum(r['region']=='Paradoxo' for r in a)}/48 chegaram ao Paradoxo; mediana da região {statistics.median(indices)} de 12.",'']
 lines+=['| Especialização | Antes: parada (campanhas) | Depois: parada (campanhas) | Mortes medianas antes → depois | Nível final mediano depois |','|---|---|---|---:|---:|']
 def stops(a):
  c=collections.Counter('Concluiu' if r['reason']=='Paradoxo derrotado' else r['region'] for r in a)
  return '; '.join(f'{k} ({v}/3)' for k,v in c.items())
 for route,name in names.items():
  before=[r for r in runs if r['route']==route and r['version']=='before'];after=[r for r in runs if r['route']==route and r['version']=='after']
  lines.append(f"| {name} | {stops(before)} | {stops(after)} | {statistics.median(r['deaths'] for r in before)} → {statistics.median(r['deaths'] for r in after)} | {statistics.median(r['level'] for r in after)} |")
  for r in before+after:summary.append(dict(scenario=label,route=route,version=r['version'],seed=r['seed'],region=r['region'],level=r['level'],fights=r['fights'],deaths=r['deaths'],reason=r['reason']))
 lines+=['','### Gargalos após as mudanças','']
 for route,name in names.items():
  a=[r for r in runs if r['route']==route and r['version']=='after'];c=collections.Counter(x['foe']['name'] for r in a for x in r['deathEvents'])
  lines.append(f"- {name}: "+'; '.join(f'{n}: {count} derrotas' for n,count in c.most_common(3))+'.')
 lines+=['']
 # Preserve full traces compactly; runner can resume directly from these records.
 (d/'results.json.gz').write_bytes(gzip.compress(json.dumps({'baseline':'601d32f','scenario':label,'runs':runs},ensure_ascii=False).encode(),compresslevel=9))
lines += ['## Alterações avaliadas', '', 'W = piso(1,4L) para os custos que anteriormente usavam piso(0,5L), inclusive os multiplicadores 2W e 3W. Custos fixos, percentuais e fatores de dano por nível foram preservados. O teto de mana dos custos de Mago continua vigente. Headshot do Sniper: 50% de chance própria de crítico, somada à chance geral e aos bônus de Mirar. Headshot Arcano: parcela de mana máxima 0,26; Emergência Arcana: parcela de mana faltante 0,61. Vallhala: +112% de dano recebido (multiplicador 2,12).', '', 'O sangramento do Samurai aplica uma pilha de 5% da vida máxima por turno, por três turnos, a cada uso que cause dano. Não duplica por projétil, não usa a vida atual e aparece explicitamente no histórico. A política da avaliação agora inclui esse valor esperado.', '', '## Interpretação', '', 'Os resultados são descritivos: três sementes, preparação acelerada e rotação heurística não demonstram a melhor build. A referência continua sendo o alcance e esforço da maioria, não a obrigação de concluir o jogo. Comparar as duas tabelas antes/depois antes de recomendar novos aumentos ou cortes; a seleção pré-definida de conjuntos não é uma busca otimizada.', '', 'A mudança de W afeta também classes que já estavam abaixo da régua. Portanto, uma redução de conclusões de Sniper/Atirador Arcano só representará aproximação se o alcance das demais rotas não recuar na mesma proporção. Conferir especialmente Samurai, Paladino, Frígido e Arquimago.', '', '## Reprodução e evidências', '', '- `node scripts/run-progression-w14-2026-11-06.cjs`', '- `node scripts/run-progression-sets-w14-2026-11-06.cjs`', '- Resumo: `docs/qa/progression-w14-summary-2026-11-06.csv`.', '- Evidências completas: `results.json.gz` nas duas pastas de QA, incluindo encontros, equipamentos, mortes e uso de habilidades.']
lines += ['','## Resultado desta rodada','','A aproximação dos extremos ainda não foi suficiente. Sniper e Atirador Arcano concluíram 3/3 nos dois cenários, antes e depois. No cenário de referência, o nível final mediano do Arcano passou de 84 para 88; com conjuntos, de 84 para 89. Para o Sniper, ficou em 85 na referência e passou de 91 para 87 com conjuntos. Isso não prova que a redução de crítico aumentou sua força: as sequências de RNG e os encontros divergem.','','Samurai continua abaixo da régua: na referência passou de três bloqueios no Panteão para dois no Panteão e um no Cataclismo; com conjuntos, passou de dois no Cataclismo para apenas um. A política agora reconhece o sangramento, portanto os próximos testes devem investigar também a prioridade dada a Cortes Ultrassônicos e as janelas de sobrevivência, sem presumir que aumentar novamente o sangramento resolve.','','Paladino permanece no Cataclismo e sua mediana de mortes aumentou de 82 para 86 na referência e de 83 para 84 com conjuntos. Berserker também permanece no Cataclismo: 82 para 86 mortes na referência, mas 84 para 82 com conjuntos. Frígido chegou ao Paradoxo em duas sementes com conjuntos, embora continue no Cataclismo na referência. Arquimago permanece no Cataclismo na referência; com conjuntos saiu do Panteão em uma semente.','','Ninja concluiu uma campanha em cada cenário; Espreitador e Guarda Florestal chegam ao Paradoxo nas três sementes. Incendiário não concluiu nenhuma desta rodada, mas alcançou o Paradoxo nas três. Corrompido concluiu uma em cada cenário; sua diferença de alcance entre os equipamentos mostra que a build ainda influencia bastante a leitura.','','O custo por nível precisa de atenção nas classes já atrasadas: no nível 100, W passou de 50 para 140. Julgamento passou de 250 para 520 MP, e Cortes Ultrassônicos de 340 para 520 MP. Uma próxima hipótese é testar apenas os multiplicadores desses custos (Julgamento: 3W para 2W; Cortes: 2W para W), sem reverter W global ou aumentar dano de todas as classes. São sugestões, não alterações desta rodada.']
(root/'docs/analise_progressao_w14_2026-11-06.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
with (root/'docs/qa/progression-w14-summary-2026-11-06.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]));w.writeheader();w.writerows(summary)
print('\n'.join(lines[:14]));print('Generated 192-run report and complete compressed traces.')
